∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {g : ℝ × Breakdown.Space → E} {t : ℝ}
  {x : Breakdown.Space},
  DifferentiableAt ℝ g (t, x) → ∀ (a : Breakdown.Space), (fderiv ℝ (fun y => g (t, y)) x) a = (fderiv ℝ g (t, x)) (0, a)

∀ {k : ℕ} {f : Breakdown.Space → Breakdown.Freq.CSpace}
  (hf : MeasureTheory.MemLp f 1 (Breakdown.SmoothFlow.weightL1Measure k)),
  Breakdown.SmoothFlow.toWeightL1 k f = MeasureTheory.MemLp.toLp f hf

∀ {x : ℝ → ↥Breakdown.Freq.X} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space} {M : ℝ},
  Breakdown.WeakProfile.IsSliceCurve x W G M → ∀ (s : ℝ), ↑↑(Breakdown.Freq.velocity (x s)) =ᵐ[MeasureTheory.volume] W s

∀ {a : Breakdown.Space × Breakdown.Space → Breakdown.Space}
  {b : Breakdown.Space × Breakdown.Space → Breakdown.Freq.CSpace},
  Measurable a → Measurable b → Measurable fun p => Breakdown.SmoothFlow.freqDot (a p) (b p)

∀ {x : ℝ → ↥Breakdown.Freq.X} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space} {M : ℝ},
  Breakdown.WeakProfile.IsSliceCurve x W G M → ∀ (s : ℝ), ‖x s‖ ≤ M
